package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class TargetOrder71Test {
 Context c;@Before public void setup(){c=RuntimeEnvironment.getApplication();}
 File image(String name)throws Exception{Bitmap b=Bitmap.createBitmap(24,24,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);File f=TargetStore.save(c,b);b.recycle();new TargetOptions(false,1080,null,name).save(c,f);return f;}
 @Test public void movesBothDirectionsWithoutChangingIdentityAndAppendsNewImages()throws Exception{File a=image("a"),b=image("b"),d=image("c");TargetOrder.move(a.getParentFile(),d,0);assertEquals(Arrays.asList(d,a,b),TargetStore.files(c));assertEquals("c",TargetOptions.load(c,d).name);assertFalse(TargetOptions.load(c,d).enabled);TargetOrder.move(a.getParentFile(),d,2);assertEquals(Arrays.asList(a,b,d),TargetStore.files(c));TargetOrder.move(a.getParentFile(),b,0);File e=image("d");assertEquals(Arrays.asList(b,a,d,e),TargetStore.files(c));assertTrue(a.exists());}
 @Test public void copiesAndExportsInDisplayOrderAndIsolatesSlotsAndActions()throws Exception{File a=image("a"),b=image("b"),d=image("c");TargetOrder.move(a.getParentFile(),d,0);PresetStore.copyCurrent(c,1,"Copy");List<File> copy=PresetStore.files(PresetStore.folder(c,1));assertEquals("c",TargetOptions.load(c,copy.get(0)).name);TargetOrder.move(copy.get(0).getParentFile(),copy.get(0),2);assertEquals(d,TargetStore.files(c).get(0));ByteArrayOutputStream bytes=new ByteArrayOutputStream();PresetArchive.exportSlot(c,0,bytes);try(PresetArchive.Staged staged=PresetArchive.stage(c,new ByteArrayInputStream(bytes.toByteArray()))){PresetArchive.install(c,staged,2,PresetStore.folder(c,2).getName());assertEquals("c",TargetOptions.load(c,TargetStore.files(c).get(0)).name);}assertTrue(TargetStore.files(ActionType.scope(c,ActionType.BACK)).isEmpty());}
 @Test public void staleMoveCannotOverwriteSavedOrder()throws Exception{File a=image("a"),b=image("b");TargetOrder.move(a.getParentFile(),b,0);try{TargetOrder.move(a.getParentFile(),a,8);fail();}catch(IOException expected){}assertEquals(Arrays.asList(b,a),TargetStore.files(c));assertTrue(a.delete());assertEquals(Collections.singletonList(b),TargetStore.files(c));}
 @Test public void crossPagePositionControlMovesImage39ToFirst()throws Exception{List<File> files=new ArrayList<>();for(int i=0;i<40;i++)files.add(image("item"+i));Activity a=Robolectric.buildActivity(Activity.class).setup().get();TargetGrid.position(a,files.get(38),()->{});org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();EditText input=findInput(dialog.getWindow().getDecorView());input.setText("1");dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(files.get(38),TargetStore.files(c).get(0));a.finish();}
 @Test public void droppingLastTileOnFirstMovesAndCancelledDragDoesNot()throws Exception{File first=image("first"),last=image("last");Activity a=Robolectric.buildActivity(Activity.class).setup().get();LinearLayout body=new LinearLayout(a);a.setContentView(body);TargetGrid.add(a,body,Arrays.asList(first,last),0,2,()->{});View tile=((ViewGroup)body.getChildAt(0)).getChildAt(0);
 assertTrue(tile.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,last)));tile.dispatchDragEvent(event(DragEvent.ACTION_DRAG_LOCATION,last));assertEquals(.65f,tile.getAlpha(),.001f);tile.dispatchDragEvent(event(DragEvent.ACTION_DRAG_ENDED,last));assertEquals(first,TargetStore.files(c).get(0));assertEquals(1f,tile.getAlpha(),0);
 tile.dispatchDragEvent(event(DragEvent.ACTION_DRAG_STARTED,last));assertTrue(tile.dispatchDragEvent(event(DragEvent.ACTION_DROP,last)));assertEquals(last,TargetStore.files(c).get(0));a.finish();}
 static DragEvent event(int action,File file){DragEvent e=org.robolectric.util.ReflectionHelpers.callConstructor(DragEvent.class);org.robolectric.util.ReflectionHelpers.setField(e,"mAction",action);org.robolectric.util.ReflectionHelpers.setField(e,"mLocalState",file);return e;}
 static EditText findInput(View v){if(v instanceof EditText)return(EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText found=findInput(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
}
